        call("POST", "/reservations/1/confirmation", null);
        call("POST", "/reservations/2/confirmation", null);
        call("POST", "/reservations/2/cancellation", null);

        HttpResponse<String> occ = call("GET", "/reports/occupancy?date=2027-03-11", null);
