                reservation,room,check_in,check_out,status,amount
                1,201,2027-03-10,2027-03-12,CONFIRMED,779.80
                2,101,2027-03-11,2027-03-13,CANCELLED,424.83
                total,1204.63
                """, call("GET", "/reports/revenue?month=2027-03", null).body());
    }
}
